import "server-only";
import { redirect } from "next/navigation";
import { createClient } from "@/lib/supabase/server";
import { type ProfileRow, type UserRole } from "@/lib/supabase/types";

/** The authenticated user, or null when signed out. */
export async function getUser() {
  const supabase = await createClient();
  const {
    data: { user },
  } = await supabase.auth.getUser();
  return user;
}

/** The signed-in user's profile row (role, name, …), or null. */
export async function getProfile(): Promise<ProfileRow | null> {
  const supabase = await createClient();
  const {
    data: { user },
  } = await supabase.auth.getUser();
  if (!user) return null;

  const { data } = await supabase
    .from("profiles")
    .select("*")
    .eq("id", user.id)
    .maybeSingle();

  return data ?? null;
}

/**
 * Require an authenticated user with one of the given roles. Redirects to
 * /signin when signed out, or to the role's home when the role doesn't match.
 * Use at the top of protected Server Components and actions (CLAUDE.md rule 5).
 */
export async function requireRole(
  roles: UserRole | UserRole[],
): Promise<ProfileRow> {
  const allowed = Array.isArray(roles) ? roles : [roles];
  const profile = await getProfile();

  if (!profile) redirect("/signin");
  if (!allowed.includes(profile.role)) redirect(homeForRole(profile.role));

  return profile;
}

/** The default landing route for a given role. */
export function homeForRole(role: UserRole): string {
  switch (role) {
    case "provider":
      return "/provider/dashboard";
    case "admin":
      return "/admin";
    case "customer":
    default:
      return "/browse";
  }
}

