-- =====================================================================
-- M3 — protect privileged provider columns. RLS lets a provider update their
-- own row, but row policies don't restrict columns; without this a provider
-- could self-approve (set status='approved') or fake their rating. This trigger
-- freezes those columns for ordinary authenticated users. Trusted server writes
-- (service role → auth.uid() is null) and admins pass through.
-- =====================================================================

create or replace function public.guard_provider_privileged_columns()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if auth.uid() is null or public.is_admin() then
    return new;
  end if;
  -- Ordinary provider editing their own profile: keep these as-is.
  new.status            := old.status;
  new.bg_check_status   := old.bg_check_status;
  new.bg_check_ref      := old.bg_check_ref;
  new.payout_account_ref := old.payout_account_ref;
  new.rating_avg        := old.rating_avg;
  new.rating_count      := old.rating_count;
  return new;
end;
$$;

