async function loadBookingForParty(bookingId: string) {
  const user = await getUser();
  if (!user) redirect("/signin");
  const supabase = await createClient();
  const { data: booking } = await supabase
    .from("bookings")
    .select("*")
    .eq("id", bookingId)
    .maybeSingle();
  // RLS already restricts to a party; double-check defensively.
  if (
    !booking ||
    (booking.customer_id !== user.id && booking.provider_id !== user.id)
  ) {
    return null;
  }
  return booking;
}

export interface StartSessionResult {
  sessionId?: string;
  error?: string;
}

/**
 * Start (or re-join) the mock call for a booking. Idempotent: returns the
 * existing session if one already exists. Creates the call session via the
 * calls adapter and the sessions row via the service-role client.
 */
export async function startSession(
  bookingId: string,
): Promise<StartSessionResult> {
  const booking = await loadBookingForParty(bookingId);
  if (!booking) return { error: "This session isn't available." };

  // A suspended customer cannot start a call (safety: protects providers).
  const profile = await getProfile();
  if (profile?.id === booking.customer_id && profile.is_suspended) {
    return { error: "Your account is paused. Please contact support." };
  }

  const supabase = await createClient();
  const { data: existing } = await supabase
    .from("sessions")
    .select("id")
    .eq("booking_id", bookingId)
    .maybeSingle();
  if (existing) return { sessionId: existing.id };

  const calls = getCalls();
  const { callSessionRef } = await calls.createSession({
    bookingId,
    providerId: booking.provider_id,
    customerId: booking.customer_id,
    maxMinutes: booking.block_minutes + 15,
  });

  const admin = createAdminClient();
  const { data: session, error } = await admin
    .from("sessions")
    .insert({
      booking_id: bookingId,
      provider_id: booking.provider_id,
      customer_id: booking.customer_id,
      call_session_ref: callSessionRef,
      started_at: new Date().toISOString(),
      block_minutes: booking.block_minutes,
      status: "in_progress",
    })
    .select("id")
    .single();
  if (error || !session) return { error: "We couldn't start the call." };

  await supabase
    .from("bookings")
    .update({ status: "in_progress" })
    .eq("id", bookingId);
